using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "WaterSwordOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/WaterSwordOmenData", order = 0)]
public class WaterSwordOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.WaterSwordOmenAction = delegate(int effectAmount, GameObject target)
		{
			if (!target.TryGetComponent<CompanionCorruptionStats>(out var component) || component.CompanionForBattle)
			{
				omenInstance.ActivateOmenFeedback();
				ActivateOmen(effectAmount, target);
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.WaterSwordOmenAction = null;
	}
}
